        except DevinAPIUnreachable as e:
            last_error = e
            if attempt < POLL_TRANSIENT_RETRY_LIMIT - 1:
                time.sleep(POLL_TRANSIENT_RETRY_DELAY_SECONDS)
    assert last_error is not None
    raise last_error

