_GIT_TIMEOUT_SECONDS = 60

# A degraded (not down) connection can make a single git network op --
# push/fetch/ls-remote -- run past the timeout even though nothing is
# actually broken; retry a few times before treating it as a real failure.
_GIT_TIMEOUT_RETRY_LIMIT = 3
_GIT_TIMEOUT_RETRY_DELAY_SECONDS = 5


def _git(*args: str, check: bool = True) -> subprocess.CompletedProcess:
    last_error: subprocess.TimeoutExpired | None = None
    for attempt in range(_GIT_TIMEOUT_RETRY_LIMIT):
        try:
            return subprocess.run(["git", *args], cwd=_REPO_ROOT, capture_output=True,
                                   text=True, check=check, timeout=_GIT_TIMEOUT_SECONDS)
        except subprocess.TimeoutExpired as e:
            last_error = e
            if attempt < _GIT_TIMEOUT_RETRY_LIMIT - 1:
                time.sleep(_GIT_TIMEOUT_RETRY_DELAY_SECONDS)
    assert last_error is not None
    raise last_error

