  if (!ts) return "";
  const d = new Date(ts);
  return d.toLocaleTimeString([], { hour12: false });
}

input.content:
:root {
  --bg: #ffffff;
  --panel: #ffffff;
  --panel-2: #f5f6f8;
  --border: #e3e6eb;
  --text: #14181f;
  --text-dim: #667085;
  --accent: #2563eb;
  --sans: "Helvetica Neue", Helvetica, Arial, sans-serif;
  --mono: "SF Mono", "JetBrains Mono", ui-monospace, Menlo, Consolas, monospace;
  --shadow: 0 1px 2px rgba(16, 24, 40, 0.04), 0 2px 8px rgba(16, 24, 40, 0.05);

  --c-idle: #94a3b8;
  --c-running: #2563eb;
  --c-pass: #16a34a;
  --c-fail: #dc2626;
  --c-stalled: #d97706;
  --c-error: #dc2626;

  color-scheme: light;
}

* {
  box-sizing: border-box;
}

html, body, #root {
  height: 100%;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: var(--sans);
}

.app {
  min-height: 100%;
  display: flex;
  flex-direction: column;
}

.app-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 24px;
  border-bottom: 1px solid var(--border);
  background: rgba(255, 255, 255, 0.9);
  backdrop-filter: blur(8px);
  position: sticky;
  top: 0;
  z-index: 10;
}

.app-title {
  font-family: var(--mono);
  font-size: 13px;
  letter-spacing: 0.12em;
  color: var(--text);
  font-weight: 700;
}

.app-title-mark {
  color: var(--accent);
  margin-right: 8px;
}

.app-header-right {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--mono);
  font-size: 11px;
  color: var(--text-dim);
}

.app-branch {
  padding: 2px 8px;
  border: 1px solid var(--border);
  border-radius: 4px;
  color: var(--accent);
  background: rgba(37, 99, 235, 0.06);
}

.conn-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  display: inline-block;
}

.conn-on {
  background: var(--c-pass);
  box-shadow: 0 0 0 3px rgba(22, 163, 74, 0.18);
  animation: pulse-dot 1.8s ease-in-out infinite;
}

.conn-off {
  background: var(--c-fail);
}

.app-controls {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 24px;
  border-bottom: 1px solid var(--border);
}

.app-controls select,
.app-controls button {
  font-family: var(--sans);
  font-size: 12px;
  background: var(--panel-2);
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 8px 12px;
}

.app-controls button {
  background: var(--accent);
  color: #ffffff;
  font-weight: 600;
  cursor: pointer;
  border: none;
}

.app-controls button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.app-launch-error {
  color: var(--c-fail);
  font-family: var(--mono);
  font-size: 12px;
}

.app-attempts-label,
.app-parallel-label,
.app-fastdemo-label {
  display: flex;
  align-items: center;
  gap: 6px;
  font-family: var(--sans);
  font-size: 12px;
  color: var(--text-dim);
}

.app-fastdemo-label {
  color: #b45309;
}

.app-attempts-label input[type="number"] {
  width: 48px;
  background: var(--panel-2);
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 6px 6px;
  font-family: var(--sans);
  font-size: 12px;
}

.app-toggle-btn {
  margin-left: auto;
  background: transparent !important;
  color: var(--text-dim) !important;
  border: 1px solid var(--border) !important;
  font-weight: 500 !important;
}

.app-toggle-btn-active {
  color: var(--accent) !important;
  border-color: var(--accent) !important;
  background: rgba(37, 99, 235, 0.06) !important;
}

.app-reset-btn {
  background: transparent !important;
  color: var(--text-dim) !important;
  border: 1px solid var(--border) !important;
  font-weight: 500 !important;
}

.app-reset-btn:hover:not(:disabled) {
  color: var(--c-fail) !important;
  border-color: var(--c-fail) !important;
}

.app-kill-btn {
  background: var(--c-fail) !important;
  color: #ffffff !important;
  font-weight: 700 !important;
  border: none !important;
}

.app-kill-btn:hover:not(:disabled) {
  filter: brightness(1.1);
}

.app-kill-result {
  color: var(--text-dim);
  font-family: var(--mono);
  font-size: 12px;
}

.app-main {
  flex: 1;
  display: grid;
  grid-template-columns: 1.3fr 1fr;
  gap: 20px;
  padding: 24px;
  align-items: start;
}

.app-graph-section,
.app-proof-section {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/* Pipeline graph */

.pipeline-graph {
  display: flex;
  align-items: center;
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 28px 20px;
  overflow-x: auto;
  box-shadow: var(--shadow);
}

.pipeline-node-wrap {
  display: flex;
  align-items: center;
  flex: 1;
  min-width: 0;
}

.pipeline-edge {
  flex: 1;
  height: 2px;
  position: relative;
  min-width: 24px;
  margin: 0 4px;
}

.pipeline-edge-line {
  height: 2px;
  background: var(--border);
  width: 100%;
}

.pipeline-edge-active .pipeline-edge-line {
  background: var(--accent);
}

.pipeline-edge-pulse {
  position: absolute;
  top: -3px;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--accent);
  box-shadow: 0 0 8px var(--accent);
  animation: travel 1.1s linear infinite;
}

@keyframes travel {
  from { left: 0%; opacity: 1; }
  to { left: 96%; opacity: 0.2; }
}

.pipeline-node {
  --node-color: var(--c-idle);
  flex-shrink: 0;
  width: 108px;
  border: 1px solid var(--node-color);
  border-radius: 10px;
  padding: 12px 10px;
  text-align: center;
  background: var(--panel-2);
  position: relative;
}

.pipeline-node-gate {
  border-radius: 6px;
  transform: rotate(0deg);
  border-style: dashed;
}

.pipeline-node-running {
  animation: glow 1.4s ease-in-out infinite;
}

@keyframes glow {
  0%, 100% { box-shadow: 0 0 0px var(--node-color); }
  50% { box-shadow: 0 0 14px var(--node-color); }
}

.pipeline-node-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--node-color);
  margin: 0 auto 8px;
}

.pipeline-node-running .pipeline-node-dot {
  animation: pulse-dot 1.1s ease-in-out infinite;
}

@keyframes pulse-dot {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.45; transform: scale(1.35); }
}

.pipeline-node-label {
  font-family: var(--sans);
  font-size: 11px;
  letter-spacing: 0.04em;
  color: var(--text);
  text-transform: uppercase;
  font-weight: 600;
}

.pipeline-node-status {
  font-family: var(--mono);
  font-size: 10px;
  color: var(--node-color);
  margin-top: 4px;
  text-transform: uppercase;
}

.pipeline-node-count {
  font-family: var(--mono);
  font-size: 10px;
  color: var(--text-dim);
  margin-top: 2px;
}

/* Agent status list */

.agent-status {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 16px 18px;
  box-shadow: var(--shadow);
}

.agent-status h3,
.proof-panel h3 {
  margin: 0 0 12px;
  font-size: 12px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-dim);
  font-family: var(--sans);
  font-weight: 700;
}

.agent-status-empty,
.proof-empty {
  color: var(--text-dim);
  font-family: var(--sans);
  font-size: 12px;
}

.agent-status-row {
  border-left: 2px solid var(--c-idle);
  padding: 8px 10px;
  margin-bottom: 6px;
  background: var(--panel-2);
  border-radius: 0 6px 6px 0;
}

.agent-status-row.status-pass { border-color: var(--c-pass); }
.agent-status-row.status-fail { border-color: var(--c-fail); }
.agent-status-row.status-error { border-color: var(--c-error); }
.agent-status-row.status-stalled { border-color: var(--c-stalled); }
.agent-status-row.status-running { border-color: var(--c-running); }
.agent-status-row.status-skipped { border-color: var(--text-dim); opacity: 0.7; }

.agent-status-top {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: var(--sans);
  font-size: 12px;
}

.agent-status-agent {
  text-transform: uppercase;
  font-weight: 700;
  letter-spacing: 0.03em;
}

.agent-status-stage {
  color: var(--text-dim);
}

.agent-status-badge {
  margin-left: auto;
  padding: 1px 6px;
  border-radius: 4px;
  font-size: 10px;
  font-family: var(--mono);
}

.badge-pass { background: rgba(22,163,74,0.12); color: var(--c-pass); }
.badge-fail { background: rgba(220,38,38,0.1); color: var(--c-fail); }
.badge-error { background: rgba(220,38,38,0.1); color: var(--c-error); }
.badge-stalled { background: rgba(217,119,6,0.12); color: var(--c-stalled); }
.badge-running { background: rgba(37,99,235,0.1); color: var(--c-running); }
.badge-skipped { background: rgba(102,112,133,0.1); color: var(--text-dim); }

.agent-status-detail {
  font-size: 12px;
  color: var(--text-dim);
  margin-top: 4px;
  word-break: break-word;
}

.agent-status-link {
  font-size: 12px;
  color: var(--accent);
  text-decoration: none;
  display: inline-block;
  margin-top: 4px;
}

.agent-status-link:hover {
  text-decoration: underline;
}

/* Proof panel */

.proof-panel {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 18px;
  box-shadow: var(--shadow);
}

.proof-section {
  margin-bottom: 22px;
}

.proof-section:last-child {
  margin-bottom: 0;
}

.proof-section-title {
  font-family: var(--sans);
  font-size: 11px;
  color: var(--text-dim);
  margin-bottom: 8px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  font-weight: 700;
}

.proof-vectors {
  display: flex;
  align-items: baseline;
  gap: 6px;
  font-family: var(--mono);
}

.proof-count {
  font-size: 28px;
  font-weight: 700;
}

.proof-count.status-pass { color: var(--c-pass); }
.proof-count.status-fail { color: var(--c-fail); }

.proof-count-sep {
  color: var(--text-dim);
  font-size: 20px;
}

.proof-count-total {
  font-size: 20px;
  color: var(--text-dim);
}

.proof-count-label {
  font-size: 11px;
  color: var(--text-dim);
  margin-left: 4px;
}

.proof-bar {
  height: 6px;
  background: var(--panel-2);
  border-radius: 3px;
  margin-top: 8px;
  overflow: hidden;
}

.proof-bar-fill {
  height: 100%;
  transition: width 0.4s ease;
}

.proof-bar-fill.status-pass { background: var(--c-pass); }
.proof-bar-fill.status-fail { background: var(--c-fail); }

.proof-synth-summary {
  font-family: var(--sans);
  font-size: 12px;
  color: var(--text-dim);
  margin-bottom: 8px;
  word-break: break-word;
}

.proof-synth-report {
  background: var(--panel-2);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 10px;
  font-size: 10px;
  color: var(--text-dim);
  overflow-x: auto;
  max-height: 180px;
}

/* Activity feed */

.activity-feed {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 16px 18px;
  box-shadow: var(--shadow);
}

.activity-feed-scroll {
  max-height: 160px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.activity-line {
  display: flex;
  gap: 8px;
  font-family: var(--mono);
  font-size: 11px;
  line-height: 1.5;
}

.activity-line-in {
  animation: line-in 0.3s ease-out;
}

@keyframes line-in {
  from { opacity: 0; transform: translateY(4px); }
  to { opacity: 1; transform: translateY(0); }
}

.activity-time {
  color: var(--text-dim);
  flex-shrink: 0;
}

.activity-agent {
  color: var(--accent);
  flex-shrink: 0;
  text-transform: uppercase;
  font-size: 10px;
  width: 72px;
}

.activity-text {
  color: var(--text);
  word-break: break-word;
}

/* Code panel */

.code-panel-header {
  display: flex;
  align-items: center;
  gap: 6px;
  font-family: var(--sans);
  font-size: 12px;
  color: var(--text-dim);
  margin-bottom: 8px;
}

.code-panel-live-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--c-pass);
  box-shadow: 0 0 0 3px rgba(22, 163, 74, 0.18);
  animation: pulse-dot 1.6s ease-in-out infinite;
  flex-shrink: 0;
}

.code-panel-agent {
  color: var(--accent);
  text-transform: uppercase;
  font-weight: 700;
}

.code-panel-path {
  color: var(--text);
  font-family: var(--mono);
}

.code-panel-download {
  margin-left: auto;
  color: var(--accent);
  text-decoration: none;
  font-family: var(--sans);
  font-size: 12px;
  font-weight: 600;
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 3px 9px;
  flex-shrink: 0;
}

.code-panel-download:hover {
  background: rgba(37, 99, 235, 0.06);
  border-color: var(--accent);
}

.code-panel-loading {
  position: relative;
}

.code-panel-body {
  background: var(--panel-2);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 10px 0;
  max-height: 320px;
  overflow: auto;
  margin: 0;
}

.code-line {
  display: flex;
  font-family: var(--mono);
  font-size: 11px;
  line-height: 1.6;
  padding: 0 10px;
  white-space: pre;
}

.code-line-in {
  animation: line-in 0.25s ease-out both;
}

.code-line-cursor {
  height: 1.6em;
}

.code-cursor {
  display: inline-block;
  width: 7px;
  height: 1.1em;
  background: var(--accent);
  animation: blink-cursor 1s step-end infinite;
}

@keyframes blink-cursor {
  0%, 49% { opacity: 1; }
  50%, 100% { opacity: 0; }
}

.code-line-no {
  color: var(--text-dim);
  opacity: 0.55;
  width: 32px;
  flex-shrink: 0;
  text-align: right;
  margin-right: 12px;
  user-select: none;
}

.tok-keyword {
  color: var(--accent);
}

.tok-number {
  color: #b45309;
}

.tok-comment {
  color: var(--text-dim);
  font-style: italic;
}

.tok-plain {
  color: var(--text);
}

/* Leaderboard */

.leaderboard {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 18px;
  box-shadow: var(--shadow);
}

.leaderboard-row {
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 12px 14px;
  margin-bottom: 10px;
  background: var(--panel-2);
}

.leaderboard-row.leaderboard-best {
  border-color: var(--c-pass);
  box-shadow: 0 0 0 1px var(--c-pass) inset;
}

.leaderboard-row-top {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: var(--sans);
  font-size: 12px;
  margin-bottom: 8px;
}

.leaderboard-branch {
  color: var(--text);
  font-family: var(--mono);
}

.leaderboard-badge {
  margin-left: auto;
  background: rgba(22, 163, 74, 0.12);
  color: var(--c-pass);
  font-size: 10px;
  padding: 2px 8px;
  border-radius: 4px;
  letter-spacing: 0.05em;
  font-weight: 700;
}

.leaderboard-bar-wrap {
  position: relative;
  height: 20px;
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 4px;
  overflow: hidden;
  display: flex;
  align-items: center;
}

.leaderboard-bar {
  height: 100%;
  background: linear-gradient(90deg, var(--accent), var(--c-pass));
  border-radius: 4px;
  min-width: 4px;
}

.leaderboard-lut {
  position: absolute;
  right: 8px;
  font-family: var(--mono);
  font-size: 10px;
  color: var(--text);
}

.leaderboard-vectors {
  margin-top: 6px;
  font-family: var(--mono);
  font-size: 10px;
  color: var(--text-dim);
}

.app-addchip-btn {
  background: transparent !important;
  color: var(--accent) !important;
  border: 1px solid var(--accent) !important;
  font-weight: 600 !important;
}

/* Add-chip modal */

.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(20, 24, 31, 0.4);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 50;
}

.modal {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 12px;
  width: 560px;
  max-width: 92vw;
  max-height: 85vh;
  overflow-y: auto;
  box-shadow: 0 8px 24px rgba(16, 24, 40, 0.14), 0 2px 6px rgba(16, 24, 40, 0.08);
}

.modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 20px;
  border-bottom: 1px solid var(--border);
}

.modal-header h3 {
  margin: 0;
  font-size: 14px;
  color: var(--text);
}

.modal-close {
  background: transparent !important;
  border: none !important;
  color: var(--text-dim) !important;
  cursor: pointer;
  font-size: 14px;
}

.modal-body {
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.modal-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  font-family: var(--sans);
  font-size: 12px;
  color: var(--text-dim);
}

.modal-field input[type="text"],
.modal-field input[type="file"] {
  background: var(--panel-2);
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 8px 10px;
  font-family: var(--sans);
  font-size: 12px;
}

.modal-note {
  font-size: 12px;
  color: var(--text-dim);
  line-height: 1.5;
  margin: 0;
}

.modal-error {
  color: var(--c-fail);
  font-family: var(--sans);
  font-size: 12px;
  margin: 0;
}

.draft-blocked-reason {
  background: var(--panel-2);
  border: 1px solid var(--c-stalled);
  border-radius: 6px;
  padding: 12px 14px;
  max-height: 320px;
  overflow-y: auto;
  font-size: 12px;
  line-height: 1.6;
  color: var(--text);
  white-space: pre-wrap;
}

.modal-primary {
  background: var(--accent) !important;
  color: #ffffff !important;
  font-weight: 700 !important;
  border: none !important;
  align-self: flex-start;
}

.modal-actions {
  display: flex;
  gap: 10px;
  justify-content: flex-end;
}

.modal-approve {
  background: var(--c-pass) !important;
  color: #ffffff !important;
  font-weight: 700 !important;
  border: none !important;
}

.modal-reject {
  background: transparent !important;
  color: var(--c-fail) !important;
  border: 1px solid var(--c-fail) !important;
}

.draft-table-wrap {
  max-height: 260px;
  overflow: auto;
  border: 1px solid var(--border);
  border-radius: 6px;
}

.draft-table {
  border-collapse: collapse;
  width: 100%;
  font-family: var(--mono);
  font-size: 11px;
}

.draft-table th,
.draft-table td {
  padding: 4px 8px;
  border-bottom: 1px solid var(--border);
  text-align: center;
  white-space: nowrap;
}

.draft-table th {
  position: sticky;
  top: 0;
  background: var(--panel-2);
  color: var(--text-dim);
}

.draft-code {
  background: var(--panel-2);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 10px;
  font-family: var(--mono);
  font-size: 10px;
  color: var(--text-dim);
  overflow-x: auto;
  max-height: 240px;
}

@media (max-width: 960px) {
  .app-main {
    grid-template-columns: 1fr;
  }
}

toolUseResult.content:
:root {
  --bg: #ffffff;
  --panel: #ffffff;
  --panel-2: #f5f6f8;
  --border: #e3e6eb;
  --text: #14181f;
  --text-dim: #667085;
  --accent: #2563eb;
  --sans: "Helvetica Neue", Helvetica, Arial, sans-serif;
  --mono: "SF Mono", "JetBrains Mono", ui-monospace, Menlo, Consolas, monospace;
  --shadow: 0 1px 2px rgba(16, 24, 40, 0.04), 0 2px 8px rgba(16, 24, 40, 0.05);

  --c-idle: #94a3b8;
  --c-running: #2563eb;
  --c-pass: #16a34a;
  --c-fail: #dc2626;
  --c-stalled: #d97706;
  --c-error: #dc2626;

  color-scheme: light;
}

* {
  box-sizing: border-box;
}

html, body, #root {
  height: 100%;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: var(--sans);
}

.app {
  min-height: 100%;
  display: flex;
  flex-direction: column;
}

.app-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 24px;
  border-bottom: 1px solid var(--border);
  background: rgba(255, 255, 255, 0.9);
  backdrop-filter: blur(8px);
  position: sticky;
  top: 0;
  z-index: 10;
}

.app-title {
  font-family: var(--mono);
  font-size: 13px;
  letter-spacing: 0.12em;
  color: var(--text);
  font-weight: 700;
}

.app-title-mark {
  color: var(--accent);
  margin-right: 8px;
}

.app-header-right {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--mono);
  font-size: 11px;
  color: var(--text-dim);
}

.app-branch {
  padding: 2px 8px;
  border: 1px solid var(--border);
  border-radius: 4px;
  color: var(--accent);
  background: rgba(37, 99, 235, 0.06);
}

.conn-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  display: inline-block;
}

.conn-on {
  background: var(--c-pass);
  box-shadow: 0 0 0 3px rgba(22, 163, 74, 0.18);
  animation: pulse-dot 1.8s ease-in-out infinite;
}

.conn-off {
  background: var(--c-fail);
}

.app-controls {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 24px;
  border-bottom: 1px solid var(--border);
}

.app-controls select,
.app-controls button {
  font-family: var(--sans);
  font-size: 12px;
  background: var(--panel-2);
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 8px 12px;
}

.app-controls button {
  background: var(--accent);
  color: #ffffff;
  font-weight: 600;
  cursor: pointer;
  border: none;
}

.app-controls button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.app-launch-error {
  color: var(--c-fail);
  font-family: var(--mono);
  font-size: 12px;
}

.app-attempts-label,
.app-parallel-label,
.app-fastdemo-label {
  display: flex;
  align-items: center;
  gap: 6px;
  font-family: var(--sans);
  font-size: 12px;
  color: var(--text-dim);
}

.app-fastdemo-label {
  color: #b45309;
}

.app-attempts-label input[type="number"] {
  width: 48px;
  background: var(--panel-2);
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 6px 6px;
  font-family: var(--sans);
  font-size: 12px;
}

.app-toggle-btn {
  margin-left: auto;
  background: transparent !important;
  color: var(--text-dim) !important;
  border: 1px solid var(--border) !important;
  font-weight: 500 !important;
}

.app-toggle-btn-active {
  color: var(--accent) !important;
  border-color: var(--accent) !important;
  background: rgba(37, 99, 235, 0.06) !important;
}

.app-reset-btn {
  background: transparent !important;
  color: var(--text-dim) !important;
  border: 1px solid var(--border) !important;
  font-weight: 500 !important;
}

.app-reset-btn:hover:not(:disabled) {
  color: var(--c-fail) !important;
  border-color: var(--c-fail) !important;
}

.app-kill-btn {
  background: var(--c-fail) !important;
  color: #ffffff !important;
  font-weight: 700 !important;
  border: none !important;
}

.app-kill-btn:hover:not(:disabled) {
  filter: brightness(1.1);
}

.app-kill-result {
  color: var(--text-dim);
  font-family: var(--mono);
  font-size: 12px;
}

.app-main {
  flex: 1;
  display: grid;
  grid-template-columns: 1.3fr 1fr;
  gap: 20px;
  padding: 24px;
  align-items: start;
}

.app-graph-section,
.app-proof-section {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/* Pipeline graph */

.pipeline-graph {
  display: flex;
  align-items: center;
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 28px 20px;
  overflow-x: auto;
  box-shadow: var(--shadow);
}

.pipeline-node-wrap {
  display: flex;
  align-items: center;
  flex: 1;
  min-width: 0;
}

.pipeline-edge {
  flex: 1;
  height: 2px;
  position: relative;
  min-width: 24px;
  margin: 0 4px;
}

.pipeline-edge-line {
  height: 2px;
  background: var(--border);
  width: 100%;
}

.pipeline-edge-active .pipeline-edge-line {
  background: var(--accent);
}

.pipeline-edge-pulse {
  position: absolute;
  top: -3px;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--accent);
  box-shadow: 0 0 8px var(--accent);
  animation: travel 1.1s linear infinite;
}

@keyframes travel {
  from { left: 0%; opacity: 1; }
  to { left: 96%; opacity: 0.2; }
}

.pipeline-node {
  --node-color: var(--c-idle);
  flex-shrink: 0;
  width: 108px;
  border: 1px solid var(--node-color);
  border-radius: 10px;
  padding: 12px 10px;
  text-align: center;
  background: var(--panel-2);
  position: relative;
}

.pipeline-node-gate {
  border-radius: 6px;
  transform: rotate(0deg);
  border-style: dashed;
}

.pipeline-node-running {
  animation: glow 1.4s ease-in-out infinite;
}

@keyframes glow {
  0%, 100% { box-shadow: 0 0 0px var(--node-color); }
  50% { box-shadow: 0 0 14px var(--node-color); }
}

.pipeline-node-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--node-color);
  margin: 0 auto 8px;
}

.pipeline-node-running .pipeline-node-dot {
  animation: pulse-dot 1.1s ease-in-out infinite;
}

@keyframes pulse-dot {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.45; transform: scale(1.35); }
}

.pipeline-node-label {
  font-family: var(--sans);
  font-size: 11px;
  letter-spacing: 0.04em;
  color: var(--text);
  text-transform: uppercase;
  font-weight: 600;
}

.pipeline-node-status {
  font-family: var(--mono);
  font-size: 10px;
  color: var(--node-color);
  margin-top: 4px;
  text-transform: uppercase;
}

.pipeline-node-count {
  font-family: var(--mono);
  font-size: 10px;
  color: var(--text-dim);
  margin-top: 2px;
}

/* Agent status list */

.agent-status {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 16px 18px;
  box-shadow: var(--shadow);
}

.agent-status h3,
.proof-panel h3 {
  margin: 0 0 12px;
  font-size: 12px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-dim);
  font-family: var(--sans);
  font-weight: 700;
}

.agent-status-empty,
.proof-empty {
  color: var(--text-dim);
  font-family: var(--sans);
  font-size: 12px;
}

.agent-status-row {
  border-left: 2px solid var(--c-idle);
  padding: 8px 10px;
  margin-bottom: 6px;
  background: var(--panel-2);
  border-radius: 0 6px 6px 0;
}

.agent-status-row.status-pass { border-color: var(--c-pass); }
.agent-status-row.status-fail { border-color: var(--c-fail); }
.agent-status-row.status-error { border-color: var(--c-error); }
.agent-status-row.status-stalled { border-color: var(--c-stalled); }
.agent-status-row.status-running { border-color: var(--c-running); }
.agent-status-row.status-skipped { border-color: var(--text-dim); opacity: 0.7; }

.agent-status-top {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: var(--sans);
  font-size: 12px;
}

.agent-status-agent {
  text-transform: uppercase;
  font-weight: 700;
  letter-spacing: 0.03em;
}

.agent-status-stage {
  color: var(--text-dim);
}

.agent-status-badge {
  margin-left: auto;
  padding: 1px 6px;
  border-radius: 4px;
  font-size: 10px;
  font-family: var(--mono);
}

.badge-pass { background: rgba(22,163,74,0.12); color: var(--c-pass); }
.badge-fail { background: rgba(220,38,38,0.1); color: var(--c-fail); }
.badge-error { background: rgba(220,38,38,0.1); color: var(--c-error); }
.badge-stalled { background: rgba(217,119,6,0.12); color: var(--c-stalled); }
.badge-running { background: rgba(37,99,235,0.1); color: var(--c-running); }
.badge-skipped { background: rgba(102,112,133,0.1); color: var(--text-dim); }

.agent-status-detail {
  font-size: 12px;
  color: var(--text-dim);
  margin-top: 4px;
  word-break: break-word;
}

.agent-status-link {
  font-size: 12px;
  color: var(--accent);
  text-decoration: none;
  display: inline-block;
  margin-top: 4px;
}

.agent-status-link:hover {
  text-decoration: underline;
}

/* Proof panel */

.proof-panel {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 18px;
  box-shadow: var(--shadow);
}

.proof-section {
  margin-bottom: 22px;
}

.proof-section:last-child {
  margin-bottom: 0;
}

.proof-section-title {
  font-family: var(--sans);
  font-size: 11px;
  color: var(--text-dim);
  margin-bottom: 8px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  font-weight: 700;
}

.proof-vectors {
  display: flex;
  align-items: baseline;
  gap: 6px;
  font-family: var(--mono);
}

.proof-count {
  font-size: 28px;
  font-weight: 700;
}

.proof-count.status-pass { color: var(--c-pass); }
.proof-count.status-fail { color: var(--c-fail); }

.proof-count-sep {
  color: var(--text-dim);
  font-size: 20px;
}

.proof-count-total {
  font-size: 20px;
  color: var(--text-dim);
}

.proof-count-label {
  font-size: 11px;
  color: var(--text-dim);
  margin-left: 4px;
}

.proof-bar {
  height: 6px;
  background: var(--panel-2);
  border-radius: 3px;
  margin-top: 8px;
  overflow: hidden;
}

.proof-bar-fill {
  height: 100%;
  transition: width 0.4s ease;
}

.proof-bar-fill.status-pass { background: var(--c-pass); }
.proof-bar-fill.status-fail { background: var(--c-fail); }

.proof-synth-summary {
  font-family: var(--sans);
  font-size: 12px;
  color: var(--text-dim);
  margin-bottom: 8px;
  word-break: break-word;
}

.proof-synth-report {
  background: var(--panel-2);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 10px;
  font-size: 10px;
  color: var(--text-dim);
  overflow-x: auto;
  max-height: 180px;
}

/* Activity feed */

.activity-feed {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 16px 18px;
  box-shadow: var(--shadow);
}

.activity-feed-scroll {
  max-height: 160px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.activity-line {
  display: flex;
  gap: 8px;
  font-family: var(--mono);
  font-size: 11px;
  line-height: 1.5;
}

.activity-line-in {
  animation: line-in 0.3s ease-out;
}

@keyframes line-in {
  from { opacity: 0; transform: translateY(4px); }
  to { opacity: 1; transform: translateY(0); }
}

.activity-time {
  color: var(--text-dim);
  flex-shrink: 0;
}

.activity-agent {
  color: var(--accent);
  flex-shrink: 0;
  text-transform: uppercase;
  font-size: 10px;
  width: 72px;
}

.activity-text {
  color: var(--text);
  word-break: break-word;
}

/* Code panel */

.code-panel-header {
  display: flex;
  align-items: center;
  gap: 6px;
  font-family: var(--sans);
  font-size: 12px;
  color: var(--text-dim);
  margin-bottom: 8px;
}

.code-panel-live-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--c-pass);
  box-shadow: 0 0 0 3px rgba(22, 163, 74, 0.18);
  animation: pulse-dot 1.6s ease-in-out infinite;
  flex-shrink: 0;
}

.code-panel-agent {
  color: var(--accent);
  text-transform: uppercase;
  font-weight: 700;
}

.code-panel-path {
  color: var(--text);
  font-family: var(--mono);
}

.code-panel-download {
  margin-left: auto;
  color: var(--accent);
  text-decoration: none;
  font-family: var(--sans);
  font-size: 12px;
  font-weight: 600;
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 3px 9px;
  flex-shrink: 0;
}

.code-panel-download:hover {
  background: rgba(37, 99, 235, 0.06);
  border-color: var(--accent);
}

.code-panel-loading {
  position: relative;
}

.code-panel-body {
  background: var(--panel-2);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 10px 0;
  max-height: 320px;
  overflow: auto;
  margin: 0;
}

.code-line {
  display: flex;
  font-family: var(--mono);
  font-size: 11px;
  line-height: 1.6;
  padding: 0 10px;
  white-space: pre;
}

.code-line-in {
  animation: line-in 0.25s ease-out both;
}

.code-line-cursor {
  height: 1.6em;
}

.code-cursor {
  display: inline-block;
  width: 7px;
  height: 1.1em;
  background: var(--accent);
  animation: blink-cursor 1s step-end infinite;
}

@keyframes blink-cursor {
  0%, 49% { opacity: 1; }
  50%, 100% { opacity: 0; }
}

.code-line-no {
  color: var(--text-dim);
  opacity: 0.55;
  width: 32px;
  flex-shrink: 0;
  text-align: right;
  margin-right: 12px;
  user-select: none;
}

.tok-keyword {
  color: var(--accent);
}

.tok-number {
  color: #b45309;
}

.tok-comment {
  color: var(--text-dim);
  font-style: italic;
}

.tok-plain {
  color: var(--text);
}

/* Leaderboard */

.leaderboard {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 18px;
  box-shadow: var(--shadow);
}

.leaderboard-row {
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 12px 14px;
  margin-bottom: 10px;
  background: var(--panel-2);
}

.leaderboard-row.leaderboard-best {
  border-color: var(--c-pass);
  box-shadow: 0 0 0 1px var(--c-pass) inset;
}

.leaderboard-row-top {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: var(--sans);
  font-size: 12px;
  margin-bottom: 8px;
}

.leaderboard-branch {
  color: var(--text);
  font-family: var(--mono);
}

.leaderboard-badge {
  margin-left: auto;
  background: rgba(22, 163, 74, 0.12);
  color: var(--c-pass);
  font-size: 10px;
  padding: 2px 8px;
  border-radius: 4px;
  letter-spacing: 0.05em;
  font-weight: 700;
}

.leaderboard-bar-wrap {
  position: relative;
  height: 20px;
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 4px;
  overflow: hidden;
  display: flex;
  align-items: center;
}

.leaderboard-bar {
  height: 100%;
  background: linear-gradient(90deg, var(--accent), var(--c-pass));
  border-radius: 4px;
  min-width: 4px;
}

.leaderboard-lut {
  position: absolute;
  right: 8px;
  font-family: var(--mono);
  font-size: 10px;
  color: var(--text);
}

.leaderboard-vectors {
  margin-top: 6px;
  font-family: var(--mono);
  font-size: 10px;
  color: var(--text-dim);
}

.app-addchip-btn {
  background: transparent !important;
  color: var(--accent) !important;
  border: 1px solid var(--accent) !important;
  font-weight: 600 !important;
}

/* Add-chip modal */

.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(20, 24, 31, 0.4);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 50;
}

.modal {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 12px;
  width: 560px;
  max-width: 92vw;
  max-height: 85vh;
  overflow-y: auto;
  box-shadow: 0 8px 24px rgba(16, 24, 40, 0.14), 0 2px 6px rgba(16, 24, 40, 0.08);
}

.modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 20px;
  border-bottom: 1px solid var(--border);
}

.modal-header h3 {
  margin: 0;
  font-size: 14px;
  color: var(--text);
}

.modal-close {
  background: transparent !important;
  border: none !important;
  color: var(--text-dim) !important;
  cursor: pointer;
  font-size: 14px;
}

.modal-body {
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.modal-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  font-family: var(--sans);
  font-size: 12px;
  color: var(--text-dim);
}

.modal-field input[type="text"],
.modal-field input[type="file"] {
  background: var(--panel-2);
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 8px 10px;
  font-family: var(--sans);
  font-size: 12px;
}

.modal-note {
  font-size: 12px;
  color: var(--text-dim);
  line-height: 1.5;
  margin: 0;
}

.modal-error {
  color: var(--c-fail);
  font-family: var(--sans);
  font-size: 12px;
  margin: 0;
}

.draft-blocked-reason {
  background: var(--panel-2);
  border: 1px solid var(--c-stalled);
  border-radius: 6px;
  padding: 12px 14px;
  max-height: 320px;
  overflow-y: auto;
  font-size: 12px;
  line-height: 1.6;
  color: var(--text);
  white-space: pre-wrap;
}

.modal-primary {
  background: var(--accent) !important;
  color: #ffffff !important;
  font-weight: 700 !important;
  border: none !important;
  align-self: flex-start;
}

.modal-actions {
  display: flex;
  gap: 10px;
  justify-content: flex-end;
}

.modal-approve {
  background: var(--c-pass) !important;
  color: #ffffff !important;
  font-weight: 700 !important;
  border: none !important;
}

.modal-reject {
  background: transparent !important;
  color: var(--c-fail) !important;
  border: 1px solid var(--c-fail) !important;
}

.draft-table-wrap {
  max-height: 260px;
  overflow: auto;
  border: 1px solid var(--border);
  border-radius: 6px;
}

.draft-table {
  border-collapse: collapse;
  width: 100%;
  font-family: var(--mono);
  font-size: 11px;
}

.draft-table th,
.draft-table td {
  padding: 4px 8px;
  border-bottom: 1px solid var(--border);
  text-align: center;
  white-space: nowrap;
}

.draft-table th {
  position: sticky;
  top: 0;
  background: var(--panel-2);
  color: var(--text-dim);
}

.draft-code {
  background: var(--panel-2);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 10px;
  font-family: var(--mono);
  font-size: 10px;
  color: var(--text-dim);
  overflow-x: auto;
  max-height: 240px;
}

@media (max-width: 960px) {
  .app-main {
    grid-template-columns: 1fr;
  }
}

