46	  // The POST resolves as soon as the server spawns the subprocess -- well
47	  // before that subprocess has done its git setup and actually created a
48	  // Devin session. Without this, the button (and the pipeline graph) show
49	  // nothing for a few seconds after clicking, looking like it did nothing.
50	  // Keep "launching" true until the first real event actually streams in.
51	  useEffect(() => {
52	    if (launching && events.length > eventCountAtLaunch.current) {
53	      setLaunching(false);
54	      clearTimeout(launchTimeoutRef.current);
55	    }
56	  }, [events, launching]);
57	
58	  async function handleLaunch() {
59	    // A single attempt is the normal, everyday action this whole UI exists
60	    // for -- warning on every click of it is just friction. Only the
61	    // elevated case (attempts > 1, especially with --parallel) is what
62	    // actually caused an unintended ~12-session spend, so only that case
