        </button>
        <select value={chip} onChange={(e) => setChip(e.target.value)}>
          {chips.map((c) => (
            <option key={c} value={c}>
              {c}
            </option>
          ))}
        </select>
        <label className="app-attempts-label">
          Attempts
          <input
            type="number"
            min={1}
            max={4}
            value={attempts}
            onChange={(e) => setAttempts(Math.max(1, Number(e.target.value) || 1))}
          />
        </label>
        <label className="app-parallel-label">
          <input
            type="checkbox"
