/* Schematic panel -- the hardware visualization */

.schematic-panel {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 18px;
  box-shadow: var(--shadow);
  display: flex;
  justify-content: center;
  transition: border-color 0.4s ease;
}

.schematic-panel svg {
  max-width: 100%;
  height: auto;
}

.schematic-trace {
  stroke: var(--border);
  stroke-width: 2;
}

.schematic-pad {
  fill: var(--text-dim);
}

.schematic-label {
  font-family: var(--mono);
  font-size: 10px;
  fill: var(--text-dim);
}

.schematic-body {
  fill: var(--panel-2);
  stroke: var(--c-idle);
  stroke-width: 2;
  transition: stroke 0.4s ease;
}

.schematic-notch {
  fill: var(--panel);
  stroke: var(--c-idle);
  stroke-width: 2;
  transition: stroke 0.4s ease;
}

.schematic-part {
  font-family: var(--sans);
  font-weight: 700;
  font-size: 13px;
  fill: var(--text);
  text-transform: uppercase;
  letter-spacing: 0.02em;
}

.schematic-part-sub {
  font-family: var(--mono);
  font-size: 9px;
  fill: var(--text-dim);
  letter-spacing: 0.08em;
}

.schematic-pin {
  opacity: 0;
  animation: schematic-pin-in 0.4s ease-out forwards;
}

@keyframes schematic-pin-in {
  from { opacity: 0; transform: translateX(-4px); }
  to { opacity: 1; transform: translateX(0); }
}

/* Running: traces + body pulse blue, pads sweep like signal activity */
.schematic-running .schematic-body,
.schematic-running .schematic-notch {
  stroke: var(--c-running);
  animation: schematic-glow 1.1s ease-in-out infinite;
}

.schematic-running .schematic-trace {
  stroke: var(--c-running);
  stroke-dasharray: 4 4;
  animation: schematic-flow 0.6s linear infinite;
}

.schematic-running .schematic-pad {
  fill: var(--c-running);
}

@keyframes schematic-flow {
  to { stroke-dashoffset: -8; }
}

@keyframes schematic-glow {
  0%, 100% { filter: drop-shadow(0 0 0 transparent); }
  50% { filter: drop-shadow(0 0 5px color-mix(in srgb, var(--c-running) 55%, transparent)); }
}

/* Verified: everything settles solid green */
.schematic-verified .schematic-body,
.schematic-verified .schematic-notch {
  stroke: var(--c-pass);
}

.schematic-verified .schematic-trace {
  stroke: var(--c-pass);
}

.schematic-verified .schematic-pad {
  fill: var(--c-pass);
}

.schematic-verified .schematic-part-sub {
  fill: var(--c-pass);
  font-weight: 700;
}

/* Failed: red tint, no motion */
.schematic-failed .schematic-body,
.schematic-failed .schematic-notch {
  stroke: var(--c-fail);
}

.schematic-failed .schematic-part-sub {
  fill: var(--c-fail);
  font-weight: 700;
}

