/* Pipeline graph */

.pipeline-graph {
  display: flex;
  align-items: center;
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 28px 20px;
  overflow-x: auto;
  box-shadow: var(--shadow);
}

.pipeline-node-wrap {
  display: flex;
  align-items: center;
  flex: 1;
  min-width: 0;
}

.pipeline-edge {
  flex: 1;
  height: 51px;
  position: relative;
  min-width: 24px;
  margin: 0 2px;
  display: flex;
  align-items: center;
}

.pipeline-edge-line {
  height: 2px;
  background: #c7ccd6;
  width: 100%;
  position: relative;
}

.pipeline-edge-line::after {
  content: "";
  position: absolute;
  right: 0;
  top: 50%;
  width: 5px;
  height: 5px;
  border-top: 2px solid #c7ccd6;
  border-right: 2px solid #c7ccd6;
  transform: translate(30%, -50%) rotate(45deg);
}

.pipeline-edge-active .pipeline-edge-line::after {
  border-color: var(--accent);
}

.pipeline-edge-active .pipeline-edge-line {
  background-image: repeating-linear-gradient(
    90deg, var(--accent) 0, var(--accent) 5px, transparent 5px, transparent 11px
  );
  background-size: 22px 2px;
  animation: dash-flow 0.7s linear infinite;
}

@keyframes dash-flow {
  to { background-position: -22px 0; }
}

.pipeline-node {
  --node-color: var(--c-idle);
  flex-shrink: 0;
  min-width: 100px;
  width: max-content;
  border: 1px solid var(--border);
  border-left: 3px solid var(--node-color);
  border-radius: 8px;
  padding: 10px 14px 9px 11px;
  text-align: left;
  background: var(--panel-2);
  position: relative;
}

.pipeline-node-gate {
  background: color-mix(in srgb, var(--node-color) 6%, var(--panel-2));
}

.pipeline-node-gate::before {
  content: "GATE";
  position: absolute;
  top: -7px;
  right: 8px;
  font-family: var(--sans);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: var(--text-dim);
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 3px;
  padding: 0 4px;
}

.pipeline-node-running {
  border-color: var(--node-color);
}

.pipeline-node-top {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 6px;
}

.pipeline-node-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--node-color);
  flex-shrink: 0;
}

.pipeline-node-running .pipeline-node-dot {
  width: 9px;
  height: 9px;
  background: transparent;
  border: 1.5px solid color-mix(in srgb, var(--node-color) 25%, transparent);
  border-top-color: var(--node-color);
  animation: spin 0.7s linear infinite;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

.pipeline-node-label {
  font-family: var(--sans);
  font-size: 11px;
  letter-spacing: 0.02em;
  color: var(--text);
  text-transform: uppercase;
  font-weight: 600;
  white-space: nowrap;
}

.pipeline-node-status {
  font-family: var(--mono);
  font-size: 10px;
  color: var(--node-color);
  margin-top: 4px;
  text-transform: uppercase;
  white-space: nowrap;
}

.pipeline-node-count {
  font-family: var(--mono);
  font-size: 10px;
  color: var(--text-dim);
  margin-top: 2px;
  white-space: nowrap;
}

