input.new_string:
/* Pipeline graph -- a fabrication-line rail with each stage as a small
   chip-package station. Stations sit in equal-width grid columns (not
   flex-sized-by-content), so spacing between them is always identical
   regardless of label length -- the rail is a separate layer underneath,
   never something that has to visually "reach" a variable-width box. */

.pipeline-rail-wrap {
  position: relative;
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 34px 24px 22px;
  box-shadow: var(--shadow);
  overflow-x: auto;
}

.pipeline-rail,
.pipeline-rail-lit {
  position: absolute;
  top: 56px;
  left: 10%;
  right: 10%;
  height: 3px;
  border-radius: 2px;
}

.pipeline-rail {
  background: #e1e4ea;
}

.pipeline-rail-lit {
  background: linear-gradient(90deg, var(--c-pass), var(--accent));
  width: 0%;
  transition: width 0.5s ease;
}

.pipeline-stations {
  position: relative;
  display: grid;
  grid-template-columns: repeat(var(--station-count), 1fr);
  min-width: 560px;
}

.pipeline-station {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 3px;
  padding: 0 6px;
}

.pipeline-chip {
  --chip-color: var(--c-idle);
  --chip-fill: var(--panel-2);
  width: 44px;
  height: 44px;
  position: relative;
  margin-bottom: 10px;
}

.pipeline-chip-active {
  filter: drop-shadow(0 0 4px color-mix(in srgb, var(--chip-color) 45%, transparent));
}

.station-icon {
  width: 100%;
  height: 100%;
  overflow: visible;
}

.station-icon-body {
  fill: var(--chip-fill);
  stroke: var(--chip-color);
  stroke-width: 2;
  transition: stroke 0.3s ease, fill 0.3s ease;
}

.station-icon-notch {
  fill: var(--panel);
  stroke: var(--chip-color);
  stroke-width: 2;
  transition: stroke 0.3s ease;
}

.station-icon-glyph {
  fill: none;
  stroke: var(--chip-color);
  stroke-width: 2.5;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.station-icon-spinner {
  fill: none;
  stroke: var(--chip-color);
  stroke-width: 2.5;
  stroke-linecap: round;
  stroke-dasharray: 40 16.6;
  transform-origin: 20px 20px;
  animation: station-spin 0.8s linear infinite;
}

@keyframes station-spin {
  to { transform: rotate(360deg); }
}

