1	import { useEffect, useRef, useState } from "react";
2	import { branchFileDownloadUrl, fetchBranchFile } from "../lib/api";
3	import { tokenizeLine } from "../lib/verilogHighlight";
4	
5	// Lines are actually added to the DOM one at a time (not just CSS-faded in
6	// all at once) so the panel reads as code landing live, not a file that
7	// popped in. Total reveal time is capped so a big file doesn't drag.
8	const MIN_STEP_MS = 18;
9	const MAX_STEP_MS = 90;
10	const MAX_REVEAL_MS = 2200;
11	
12	const AGENT_PATH = {
13	  coder: (chip) => `rtl/${chip}.v`,
14	  style: (chip) => `rtl/${chip}.v`,
15	  testbencher: (chip) => `rtl/${chip}_tb_extra.v`,
16	};
17	const CODE_STAGES = new Set(["generate", "coverage", "cleanup"]);
18	
19	function lastCodeEvent(events) {
20	  for (let i = events.length - 1; i >= 0; i--) {
21	    const e = events[i];
22	    if (e.status === "pass" && CODE_STAGES.has(e.stage) && AGENT_PATH[e.agent]) return e;
23	  }
24	  return null;
25	}
26	
27	// Shows the ACTUAL committed RTL, fetched straight from the git branch --
28	// updates live as each agent (coder -> testbencher -> style) pushes its
29	// commit, so you watch the real code land rather than a waveform of a
30	// binary counter sweep.
31	export default function CodePanel({ events }) {
32	  const latest = lastCodeEvent(events);
33	  const [code, setCode] = useState(null);
34	  const [error, setError] = useState(null);
35	  const [visibleCount, setVisibleCount] = useState(0);
36	  const timerRef = useRef(null);
37	
38	  const path = latest ? AGENT_PATH[latest.agent](latest.chip) : null;
39	
40	  useEffect(() => {
41	    if (!latest) return;
42	    setCode(null);
43	    setError(null);
44	    setVisibleCount(0);
45	    fetchBranchFile(latest.branch, path)
46	      .then(setCode)
47	      .catch((e) => setError(String(e)));
48	    // eslint-disable-next-line react-hooks/exhaustive-deps
49	  }, [latest?.branch, latest?.agent, latest?.ts]);
50	
51	  useEffect(() => {
52	    clearInterval(timerRef.current);
53	    if (!code) return undefined;
54	
55	    const totalLines = code.split("\n").length;
56	    const stepMs = Math.min(MAX_STEP_MS, Math.max(MIN_STEP_MS, MAX_REVEAL_MS / totalLines));
57	    setVisibleCount(0);
58	    let shown = 0;
59	    timerRef.current = setInterval(() => {
60	      shown += 1;
61	      setVisibleCount(shown);
62	      if (shown >= totalLines) clearInterval(timerRef.current);
63	    }, stepMs);
64	
65	    return () => clearInterval(timerRef.current);
66	  }, [code]);
67	
68	  if (!latest) return <div className="proof-empty">No code pushed yet</div>;
69	  if (error) return <div className="proof-empty">Could not load {path} ({error})</div>;
70	  if (!code) return <div className="proof-empty code-panel-loading">Loading {path}…</div>;
71	
72	  const lines = code.split("\n");
73	  const shownLines = lines.slice(0, visibleCount);
74	  const stillWriting = visibleCount < lines.length;
75	
76	  return (
77	    <div className="code-panel">
78	      <div className="code-panel-header">
79	        <span className="code-panel-live-dot" aria-hidden="true" />
80	        <span className="code-panel-agent">{latest.agent}</span> just wrote{" "}
81	        <span className="code-panel-path">{path}</span>
82	        <a
83	          className="code-panel-download"
84	          href={branchFileDownloadUrl(latest.branch, path)}
85	          download
86	        >
87	          ↓ Download
88	        </a>
89	      </div>
90	      <pre className="code-panel-body">
91	        {shownLines.map((line, i) => (
92	          <div className="code-line code-line-in" key={i}>
93	            <span className="code-line-no">{i + 1}</span>
94	            <span className="code-line-text">
95	              {tokenizeLine(line).map((tok, j) => (
96	                <span key={j} className={`tok-${tok.kind}`}>
97	                  {tok.text}
98	                </span>
99	              ))}
100	            </span>
101	          </div>
