    n = spec.input_bits
    in_names = [p.name for p in spec.inputs]
    rows = []
    for idx in indices:
        bits = [(idx >> (n - 1 - i)) & 1 for i in range(n)]
        in_map = dict(zip(in_names, bits))
        out_map = spec.golden_fn(in_map)
        rows.append({**in_map, **out_map})

    return {"chip_id": chip_id, "rows": rows}


