export default function SchematicPanel({ events }) {
  const chipId = currentChip(events);
  const [ports, setPorts] = useState(null);
  const [error, setError] = useState(null);
  // Real (input, output) rows from the golden model, cycled through so the
  // diagram shows the chip actually behaving instead of just labeled pins.
  // Best-effort: if this fails to load, the static pinout still renders
  // fine without it.
  const [sampleRows, setSampleRows] = useState(null);
  const [sampleIndex, setSampleIndex] = useState(0);

  useEffect(() => {
    if (!chipId) {
      setPorts(null);
      setSampleRows(null);
      return;
    }
    setError(null);
    setSampleRows(null);
    setSampleIndex(0);
    fetchChipPorts(chipId)
      .then(setPorts)
      .catch((e) => setError(String(e)));
    fetchChipSampleVectors(chipId, SAMPLE_COUNT)
      .then((d) => setSampleRows(d.rows))
      .catch(() => setSampleRows(null));
  }, [chipId]);

  useEffect(() => {
    if (!sampleRows || sampleRows.length < 2) return undefined;
    const id = setInterval(() => {
      setSampleIndex((i) => (i + 1) % sampleRows.length);
    }, SAMPLE_CYCLE_MS);
    return () => clearInterval(id);
  }, [sampleRows]);

