              <text x={stubEnd + 6} y={y - 4} textAnchor="start" className="schematic-label">
                {name}
              </text>
            </g>
          );
        })}

        <rect
          x={bodyX}
          y={bodyY}
          width={BODY_WIDTH}
          height={bodyHeight}
          rx={6}
