          d={`M ${bodyX + BODY_WIDTH / 2 - 9} ${bodyY} a 9 9 0 0 0 18 0`}
          className="schematic-notch"
        />
        <text x={bodyX + BODY_WIDTH / 2} y={centerY - 2} textAnchor="middle" className="schematic-part">
